import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ------------------------------------------------------------
# CUDA kernel implementing FP16 Conv2d (stride=4, padding=2)
# ------------------------------------------------------------
cuda_src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void conv2d_fp16_kernel(const half* __restrict__ input,
                                   const half* __restrict__ weight,
                                   const half* __restrict__ bias,
                                   half* __restrict__ output,
                                   int batch, int in_c, int in_h, int in_w,
                                   int out_c, int out_h, int out_w,
                                   int k_h, int k_w,
                                   int stride, int padding) {
    int total = batch * out_c * out_h * out_w;
    int idx   = blockIdx.x * blockDim.x + threadIdx.x;
    int step  = blockDim.x * gridDim.x;

    for (int i = idx; i < total; i += step) {
        int tmp = i;
        int w   = tmp % out_w; tmp /= out_w;
        int h   = tmp % out_h; tmp /= out_h;
        int oc  = tmp % out_c; tmp /= out_c;
        int b   = tmp;

        float sum = bias ? __half2float(bias[oc]) : 0.0f;

        for (int ic = 0; ic < in_c; ++ic) {
            for (int kh = 0; kh < k_h; ++kh) {
                int ih = h * stride - padding + kh;
                if (ih < 0 || ih >= in_h) continue;
                for (int kw = 0; kw < k_w; ++kw) {
                    int iw = w * stride - padding + kw;
                    if (iw < 0 || iw >= in_w) continue;

                    int input_idx  = ((b * in_c + ic) * in_h + ih) * in_w + iw;
                    int weight_idx = ((oc * in_c + ic) * k_h + kh) * k_w + kw;

                    sum += __half2float(input[input_idx]) *
                           __half2float(weight[weight_idx]);
                }
            }
        }
        output[i] = __float2half(sum);
    }
}

torch::Tensor conv2d_fp16(torch::Tensor input,
                          torch::Tensor weight,
                          torch::Tensor bias) {
    // input: [N, C_in, H, W]
    // weight: [C_out, C_in, K_h, K_w]
    // bias  : [C_out] or undefined
    const int batch = input.size(0);
    const int in_c  = input.size(1);
    const int in_h  = input.size(2);
    const int in_w  = input.size(3);

    const int out_c = weight.size(0);
    const int k_h   = weight.size(2);
    const int k_w   = weight.size(3);

    const int stride   = 4;   // fixed per reference model
    const int padding  = 2;   // fixed per reference model

    const int out_h = (in_h + 2 * padding - k_h) / stride + 1;
    const int out_w = (in_w + 2 * padding - k_w) / stride + 1;

    auto output = torch::empty({batch, out_c, out_h, out_w}, input.options());

    const int threads = 256;
    const int blocks  = (batch * out_c * out_h * out_w + threads - 1) / threads;

    conv2d_fp16_kernel<<<blocks, threads>>>(
        reinterpret_cast<half*>(input.data_ptr()),
        reinterpret_cast<half*>(weight.data_ptr()),
        bias.defined() ? reinterpret_cast<half*>(bias.data_ptr()) : nullptr,
        reinterpret_cast<half*>(output.data_ptr()),
        batch, in_c, in_h, in_w,
        out_c, out_h, out_w,
        k_h, k_w,
        stride, padding);

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA kernel launch error: %s\\n", cudaGetErrorString(err));
    }

    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv2d_fp16", &conv2d_fp16, "FP16 Conv2d (custom kernel)");
}
'''

# Compile the extension inline
conv2d_custom = load_inline(
    name='conv2d_custom',
    cpp_sources='',
    cuda_sources=cuda_src,
    functions=['conv2d_fp16'],
    verbose=False,
)

# ------------------------------------------------------------
# PyTorch model that uses the custom kernel
# ------------------------------------------------------------
class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        # Conv2d parameters matching the reference model
        self.weight = nn.Parameter(
            torch.randn(96, 3, 11, 11, dtype=torch.float16)
        )
        self.bias = nn.Parameter(
            torch.randn(96, dtype=torch.float16)
        )

    def forward(self, x):
        # x is expected to be FP16 and on CUDA
        return conv2d_custom.conv2d_fp16(x, self.weight, self.bias)

# ------------------------------------------------------------
# Example usage (mirrors reference test code)
# ------------------------------------------------------------
if __name__ == "__main__":
    batch_size = 256
    num_classes = 1000

    def get_inputs():
        return [torch.rand(batch_size, 3, 224, 224, dtype=torch.float16, device='cuda')]

    def get_init_inputs():
        return [num_classes]

    model = ModelNew().cuda().half()
    inputs = get_inputs()[0]
    out = model(inputs)
    print(out.shape)   # Expected: torch.Size([256, 96, 55, 55])
